{
  "name": "Prior 电动 XY 载物台",
  "name_en": "Prior Motorized XY Stage",
  "manufacturer": "Prior",
  "description": "用于显微镜或实验平台样品定位的电动二维平移载物台，可读取当前位置，并执行 X/Y 方向微米级相对移动与指定坐标绝对移动，同时检查软限位和硬限位以避免超程。",
  "description_en": "A motorized 2D translation stage for sample positioning on microscopes or laboratory platforms. It can report the current position, perform micron-scale relative motion in X and Y, move to specified coordinates, and check soft and hard travel limits to avoid overtravel.",
  "actions": [
    {
      "action_name": "auto-getPosition",
      "description": "获取载物台当前 XY 位置。",
      "description_en": "Get the current XY position of the stage."
    },
    {
      "action_name": "auto-MoveRelX",
      "description": "沿 X 方向相对移动载物台。",
      "description_en": "Move the stage relatively along the X axis."
    },
    {
      "action_name": "auto-MoveRelY",
      "description": "沿 Y 方向相对移动载物台。",
      "description_en": "Move the stage relatively along the Y axis."
    },
    {
      "action_name": "auto-MoveTo",
      "description": "将载物台移动到指定 XY 坐标。",
      "description_en": "Move the stage to the specified XY coordinates."
    },
    {
      "action_name": "auto-MoveAbs",
      "description": "将载物台执行绝对坐标移动。",
      "description_en": "Move the stage using absolute coordinates."
    },
    {
      "action_name": "auto-checkhardlimits",
      "description": "检查载物台硬限位状态。",
      "description_en": "Check the hard limit status of the stage."
    },
    {
      "action_name": "auto-checksoftlimit",
      "description": "检查相对移动是否会超过软限位。",
      "description_en": "Check whether a relative move would exceed the soft limits."
    },
    {
      "action_name": "auto-checksoftlimitAbs",
      "description": "检查目标绝对坐标是否超出软限位。",
      "description_en": "Check whether the target absolute coordinates exceed the soft limits."
    },
    {
      "action_name": "auto-error",
      "description": "查询指定操作的错误信息。",
      "description_en": "Query error information for a specified operation."
    }
  ],
  "tag_hints": [
    "motorized XY stage",
    "microscope stage positioning",
    "sample translation",
    "micron motion control",
    "soft limit checking",
    "hard limit detection",
    "Prior Scientific"
  ]
}

